head.script:

	scwin.onpageload = function() {
		var dataJson = [
			{"col1":"D","col2":"201","col3":"301","col4":"401","col5":"501"},
			{"col1":"D","col2":"202","col3":"302","col4":"402","col5":"502"},
			{"col1":"D","col2":"203","col3":"303","col4":"403","col5":"503"},
			{"col1":"T","col2":"999","col3":"999","col4":"999","col5":"504"},
			{"col1":"T","col2":"205","col3":"305","col4":"405","col5":"505"},
			{"col1":"D","col2":"206","col3":"306","col4":"406","col5":"506"},
			{"col1":"D","col2":"207","col3":"307","col4":"407","col5":"507"}
		]
		dataList1.setJSON(dataJson);
        dataFilterList.setJSON(dataList1.getAllJSON(), false);

        gridView1.mergeCell({"rowIndex": 3, "colIndex": 0, "rowSpan": 2});
		gridView1.mergeCell({"rowIndex": 4, "colIndex": 1, "colSpan": 3});
	};

	scwin.onpageunload = function() {

	};


scwin.trigger1_onclick = function(e) {
	dataFilterList.setBroadcast(false);
    dataFilterList.setJSON(dataList1.getMatchedJSON("col1", "D"));
//	dataList1.setColumnFilter(
//		{type:'row', colIndex: 'col1', key:"D", condition: 'and', exactMatch: true}
//		
//	);

	dataFilterList.setBroadcast(true, true);

};

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_4_1').innerText == '207';
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_4_1').getAttribute('colspan') == '3';
	}	
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
